CREATE OR REPLACE FUNCTION workhub_private.c_cmd_withdraw(p_ctx workhub_private.actor_context, p_cmd jsonb, p_eff jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE c workhub.collections; u workhub.collection_units; sv workhub.submission_versions; v_window text; v_withdrawal text;
BEGIN
  u := workhub_private.c_lock_unit(p_ctx, p_cmd ->> 'requestId', p_cmd ->> 'unitId');
  IF NOT (u.responsible_membership_id = p_ctx.membership_id AND u.responsible_account_id = p_ctx.account_id) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  -- 직접 철회는 승인된 학교 제출 정책이 허용할 때만
  IF NOT (p_eff ->> 'allowWithdrawal')::boolean THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  IF u.version <> (p_cmd ->> 'expectedVersion')::integer THEN RAISE EXCEPTION 'CONFLICT'; END IF;
  SELECT * INTO sv FROM workhub.submission_versions WHERE school_id = u.school_id AND unit_id = u.id AND id = p_cmd ->> 'submissionId';
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF u.current_submission_id IS DISTINCT FROM sv.id THEN RAISE EXCEPTION 'CONFLICT'; END IF;
  -- 승인 완료판은 직접 철회하지 않는다
  IF EXISTS (SELECT 1 FROM workhub.submission_reviews r WHERE r.school_id = sv.school_id AND r.submission_id = sv.id AND r.decision = 'accepted') THEN
    RAISE EXCEPTION 'FORBIDDEN';
  END IF;
  SELECT * INTO c FROM workhub.collections WHERE school_id = u.school_id AND id = u.collection_id;
  IF clock_timestamp() >= c.due_at THEN
    v_window := workhub_private.c_open_window(p_ctx, u.id, 'withdraw');
    IF v_window IS NULL THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  END IF;
  INSERT INTO workhub.submission_withdrawals (school_id, unit_id, submission_id, actor_account_id, actor_membership_id, reason, correction_window_id)
  VALUES (u.school_id, u.id, sv.id, p_ctx.account_id, p_ctx.membership_id, p_cmd ->> 'reason', v_window) RETURNING id INTO v_withdrawal;
  -- 이 판이 충족한 보완은 무효로 표시하고 보완 의무를 다시 연다
  UPDATE workhub.correction_requests SET state = 'open'
   WHERE school_id = u.school_id AND id IN (SELECT correction_request_id FROM workhub.collection_correction_fulfillments
                                             WHERE school_id = u.school_id AND submission_id = sv.id AND invalidated_at IS NULL);
  UPDATE workhub.collection_correction_fulfillments SET invalidated_at = clock_timestamp(), invalidated_by_withdrawal_id = v_withdrawal
   WHERE school_id = u.school_id AND submission_id = sv.id AND invalidated_at IS NULL;
  -- 무검토형: 현재판·완료본을 모두 비운다(이전판 자동 부활 없음). 검토형: 현재판을 완료본으로 되돌린다.
  UPDATE workhub.collection_units SET
         current_submission_id = CASE WHEN c.review_mode = 'none' THEN NULL ELSE effective_submission_id END,
         effective_submission_id = CASE WHEN c.review_mode = 'none' THEN NULL ELSE effective_submission_id END,
         version = u.version + 1
   WHERE id = u.id;
  RETURN jsonb_build_object('type', 'collection_unit', 'id', u.id, 'version', u.version + 1, 'requestId', u.collection_id);
END $function$

CREATE OR REPLACE FUNCTION workhub_private.c_cmd_submit(p_ctx workhub_private.actor_context, p_cmd jsonb, p_eff jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE c workhub.collections; u workhub.collection_units; s workhub.collection_schemas; d workhub.unit_drafts; cr workhub.correction_requests;
  sv workhub.submission_versions; f workhub.file_objects; v_code text; v_now timestamptz := clock_timestamp(); v_prior boolean;
  v_window text; v_cr_id text := p_cmd ->> 'correctionRequestId'; v_files text[]; v_count integer;
BEGIN
  u := workhub_private.c_lock_unit(p_ctx, p_cmd ->> 'requestId', p_cmd ->> 'unitId');
  IF NOT (u.responsible_membership_id = p_ctx.membership_id AND u.responsible_account_id = p_ctx.account_id) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  IF u.version <> (p_cmd ->> 'expectedVersion')::integer THEN RAISE EXCEPTION 'CONFLICT'; END IF;
  SELECT * INTO c FROM workhub.collections WHERE school_id = p_ctx.school_id AND id = u.collection_id;
  SELECT * INTO s FROM workhub.collection_schemas WHERE school_id = p_ctx.school_id AND id = u.active_schema_id;
  SELECT * INTO d FROM workhub.unit_drafts WHERE school_id = p_ctx.school_id AND id = p_cmd ->> 'draftId' AND unit_id = u.id AND schema_id = s.id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF d.version <> (p_cmd ->> 'expectedDraftVersion')::integer THEN RAISE EXCEPTION 'CONFLICT'; END IF;
  -- 상세 1회 응답 한도(제출판 1,000)를 넘기면 이력이 잘린다 → 더 받지 않는다.
  -- 단위 잠금만으로는 다른 단위의 동시 제출을 막지 못하므로, 세기 전에 수합 단위 잠금을 잡는다(트랜잭션 끝에 풀림).
  -- 잠금 순서는 항상 단위 행 → 이 잠금이고, 이 잠금을 잡은 뒤 다른 단위 행을 잠그지 않으므로 순환 대기가 없다.
  PERFORM pg_advisory_xact_lock(hashtextextended('workhub.collection.submit:' || c.school_id || chr(31) || c.id, 0));
  IF (SELECT count(*) FROM workhub.submission_versions WHERE school_id = c.school_id AND collection_id = c.id) >= 1000 THEN
    RAISE EXCEPTION 'NOT_READY';
  END IF;
  v_prior := EXISTS (SELECT 1 FROM workhub.submission_versions WHERE school_id = u.school_id AND unit_id = u.id);
  IF v_prior AND workhub_private.js_trim(p_cmd ->> 'reason') = '' THEN RAISE EXCEPTION 'INVALID_INPUT'; END IF;
  IF v_cr_id IS NOT NULL THEN
    SELECT * INTO cr FROM workhub.correction_requests WHERE school_id = u.school_id AND unit_id = u.id AND id = v_cr_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
    IF cr.state <> 'open' THEN RAISE EXCEPTION 'CONFLICT'; END IF;
  END IF;
  -- 마감(학교 시간대 다음 날 00:00) 뒤 재제출은 열린 보완 요청 또는 정정창이 있어야 한다. 최초 지연 제출은 받는다.
  IF v_prior AND v_now >= c.due_at AND v_cr_id IS NULL THEN
    v_window := workhub_private.c_open_window(p_ctx, u.id, 'submit');
    IF v_window IS NULL THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  END IF;
  -- 필수 응답은 제출 때 검사한다
  IF EXISTS (SELECT 1 FROM workhub.collection_fields fl WHERE fl.school_id = s.school_id AND fl.schema_id = s.id AND fl.required AND (
        (fl.field_key = 'text' AND workhub_private.js_trim(d.answers ->> 'text') = '')
     OR (fl.field_key = 'number' AND d.answers -> 'number' = 'null'::jsonb)
     OR (fl.field_key = 'files' AND NOT EXISTS (SELECT 1 FROM workhub.unit_draft_files df WHERE df.school_id = d.school_id AND df.draft_id = d.id AND df.unlinked_at IS NULL)))) THEN
    RAISE EXCEPTION 'INVALID_INPUT';
  END IF;
  v_files := ARRAY(SELECT df.file_id FROM workhub.unit_draft_files df WHERE df.school_id = d.school_id AND df.draft_id = d.id AND df.unlinked_at IS NULL ORDER BY df.file_id);
  PERFORM 1 FROM workhub.file_objects WHERE school_id = p_ctx.school_id AND id = ANY (v_files) ORDER BY id FOR UPDATE;
  -- 첨부 개수: 저장 당시가 아니라 제출 시점의 요청 정책 ∩ 오늘 유효한 정책으로 다시 본다(이미 받은 과거 제출판은 그대로).
  IF cardinality(v_files) > 0 AND (s.file_policy IS NULL
       OR cardinality(v_files) > least((s.file_policy ->> 'maxFiles')::integer, (p_eff -> 'file' ->> 'maxFiles')::integer)) THEN
    RAISE EXCEPTION 'FILE_FAILED';
  END IF;
  FOR f IN SELECT * FROM workhub.file_objects WHERE school_id = p_ctx.school_id AND id = ANY (v_files) LOOP
    v_code := workhub_private.c_file_problem(f, p_eff, s.file_policy);
    IF v_code IS NOT NULL THEN RAISE EXCEPTION '%', v_code; END IF;
  END LOOP;
  SELECT COALESCE(max(version_no), 0) + 1 INTO v_count FROM workhub.submission_versions WHERE school_id = u.school_id AND unit_id = u.id;
  INSERT INTO workhub.submission_versions (school_id, collection_id, unit_id, schema_id, version_no, previous_submission_id,
      submitted_by_account_id, submitted_by_membership_id, responsible_account_id, source_draft_id, source_draft_version, answers, review_mode,
      receipt_at, receipt_date, due_on_snapshot, due_snapshot, due_change_revision, is_late, correction_reason, correction_request_id,
      correction_window_id, request_id)
  VALUES (u.school_id, u.collection_id, u.id, s.id, v_count, u.current_submission_id,
      p_ctx.account_id, p_ctx.membership_id, u.responsible_account_id, d.id, d.version, d.answers, c.review_mode,
      v_now, (v_now AT TIME ZONE p_ctx.school_timezone)::date, c.due_on, c.due_at, c.due_change_revision, v_now >= c.due_at,
      p_cmd ->> 'reason', v_cr_id, v_window, p_cmd ->> 'requestKey')
  RETURNING * INTO sv;
  INSERT INTO workhub.submission_files (school_id, submission_id, file_id, ordinal, sha256, size_bytes,
      safety_policy_scope_key, safety_policy_version_id, common_safety_policy_scope_key, common_safety_policy_version_id)
  SELECT sv.school_id, sv.id, fo.id, df.ordinal, fo.sha256, fo.size_bytes,
         fo.safety_policy_scope_key, fo.safety_policy_version_id, fo.common_safety_policy_scope_key, fo.common_safety_policy_version_id
    FROM workhub.unit_draft_files df JOIN workhub.file_objects fo ON fo.school_id = df.school_id AND fo.id = df.file_id
   WHERE df.school_id = d.school_id AND df.draft_id = d.id AND df.unlinked_at IS NULL;
  IF v_cr_id IS NOT NULL THEN
    INSERT INTO workhub.collection_correction_fulfillments (school_id, unit_id, correction_request_id, submission_id)
    VALUES (u.school_id, u.id, cr.id, sv.id);
    UPDATE workhub.correction_requests SET state = 'fulfilled' WHERE id = cr.id;
  END IF;
  UPDATE workhub.collection_units SET current_submission_id = sv.id,
         effective_submission_id = CASE WHEN c.review_mode = 'none' THEN sv.id ELSE effective_submission_id END,
         first_submission_id = COALESCE(first_submission_id, sv.id),
         first_valid_submitted_at = COALESCE(first_valid_submitted_at, sv.receipt_at),
         first_submission_late = COALESCE(first_submission_late, sv.is_late),
         version = u.version + 1
   WHERE id = u.id;
  RETURN jsonb_build_object('type', 'submission', 'id', sv.id, 'version', sv.version_no, 'requestId', u.collection_id);
END $function$

CREATE OR REPLACE FUNCTION workhub_private.legacy_gate(p_lock boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'FORBIDDEN' USING DETAIL = '로그인이 필요합니다.'; END IF;
  IF p_lock THEN PERFORM 1 FROM public.users WHERE id = v_uid::text FOR SHARE; END IF;
  IF NOT (public.is_approved() AND public.get_my_role() IS NOT DISTINCT FROM 'superadmin') THEN
    RAISE EXCEPTION 'FORBIDDEN' USING DETAIL = '승인된 공개 대상만 업무실을 쓸 수 있습니다.';
  END IF;
  RETURN v_uid;
END $function$

CREATE OR REPLACE FUNCTION workhub_private.t2_exchange_calc(p_ctx workhub_private.actor_context, i jsonb, p_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a workhub.timetable_lessons; o workhub.timetable_lessons; va jsonb; vo jsonb; v_changes jsonb; v_blockers jsonb := '[]'::jsonb; v_ids text[]; v_c text[];
        v_bad jsonb; v_closed jsonb; v_tz text := p_ctx.school_timezone;
BEGIN
  PERFORM workhub_private.t2_exchange_input(i);
  SELECT * INTO a FROM workhub.timetable_lessons WHERE school_id = p_ctx.school_id AND id = i ->> 'lessonId';
  IF a.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF NOT (p_ctx.membership_id = ANY (a.teacher_ids)) OR a.changed_by = 'school_day' THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  IF to_jsonb(a.version) <> i -> 'expectedVersion' OR a.state <> 'scheduled' OR a.starts_at <= p_at THEN RAISE EXCEPTION 'CONFLICT'; END IF;
  va := workhub_private.t2_vlesson(a, p_ctx, p_at);
  IF i ->> 'kind' = 'move' THEN
    IF NOT ((va -> 'allowedTargets') @> jsonb_build_array(i -> 'target')) OR i -> 'target' = va -> 'time'
       OR workhub_private.t2_parse_ts(i #> '{target,startsAt}', true) <= p_at THEN
      RAISE EXCEPTION 'INVALID_INPUT';
    END IF;
    v_changes := jsonb_build_array(jsonb_build_object('before', va, 'after', va || jsonb_build_object('version', a.version + 1, 'time', i -> 'target')));
  ELSE
    SELECT * INTO o FROM workhub.timetable_lessons WHERE school_id = p_ctx.school_id AND id = i ->> 'otherLessonId';
    IF o.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
    IF to_jsonb(o.version) <> i -> 'otherExpectedVersion' OR o.state <> 'scheduled' OR o.starts_at <= p_at THEN RAISE EXCEPTION 'CONFLICT'; END IF;
    vo := workhub_private.t2_vlesson(o, p_ctx, p_at);
    IF NOT ((va -> 'allowedTargets') @> jsonb_build_array(vo -> 'time')) OR NOT ((vo -> 'allowedTargets') @> jsonb_build_array(va -> 'time'))
       OR va -> 'time' = vo -> 'time' THEN
      RAISE EXCEPTION 'INVALID_INPUT';
    END IF;
    v_changes := jsonb_build_array(jsonb_build_object('before', va, 'after', va || jsonb_build_object('version', a.version + 1, 'time', vo -> 'time')),
                                   jsonb_build_object('before', vo, 'after', vo || jsonb_build_object('version', o.version + 1, 'time', va -> 'time')));
  END IF;
  v_ids := ARRAY(SELECT c #>> '{after,id}' FROM jsonb_array_elements(v_changes) c);
  -- 내가 담당한 수업에 그 사이 다른 요청이 걸렸으면 화면이 본 수업(요청 가능)과 달라졌다 → CONFLICT(앱이 다시 조회).
  --   앱은 before 가 화면의 수업과 같아야 받으므로, 차단 사유로 돌려주면 응답 오류(INVALID_RESPONSE)로 보인다.
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_changes) c
              WHERE c #> '{before,teachers}' @> jsonb_build_array(jsonb_build_object('id', p_ctx.membership_id))
                AND workhub_private.t2_lesson_busy(p_ctx.school_id, c #>> '{after,id}', p_at)) THEN
    RAISE EXCEPTION 'CONFLICT';
  END IF;
  -- 차단: 진행 중 요청(상대 수업) · 자원 겹침 · 공개판 불가 조건 · 휴업일
  v_bad := (SELECT jsonb_agg(x ORDER BY x) FROM unnest(v_ids) x WHERE workhub_private.t2_lesson_busy(p_ctx.school_id, x, p_at));
  IF v_bad IS NOT NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code', 'PENDING_REQUEST',
      'message', '이 수업에 진행 중인 다른 교환 요청이 있습니다. 그 요청이 끝난 뒤 다시 확인해 주세요.', 'lessonIds', v_bad));
  END IF;
  v_c := workhub_private.t2_conflicts(p_ctx.school_id, (
    SELECT jsonb_agg(jsonb_build_object('id', l.id, 's', c #>> '{after,time,startsAt}', 'e', c #>> '{after,time,endsAt}', 'uses', l.uses))
      FROM jsonb_array_elements(v_changes) c JOIN workhub.timetable_lessons l ON l.school_id = p_ctx.school_id AND l.id = c #>> '{after,id}'), ARRAY[]::text[]);
  IF cardinality(v_c) > 0 THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code', 'RESOURCE_CONFLICT',
      'message', '옮길 시간에 같은 교사 · 학급 · 공간을 쓰는 다른 수업이 있습니다.', 'lessonIds', to_jsonb(v_c)));
  END IF;
  v_bad := (SELECT jsonb_agg(l.id ORDER BY l.id) FROM jsonb_array_elements(v_changes) c JOIN workhub.timetable_lessons l ON l.school_id = p_ctx.school_id AND l.id = c #>> '{after,id}'
             WHERE workhub_private.t2_unavailable(l.publication_id, l.uses, (c #>> '{after,time,startsAt}')::timestamptz, (c #>> '{after,time,endsAt}')::timestamptz, v_tz));
  IF v_bad IS NOT NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code', 'RESOURCE_UNAVAILABLE',
      'message', '옮길 시간은 교사 · 공간의 수업 불가 시간입니다.', 'lessonIds', v_bad));
  END IF;
  v_bad := (SELECT jsonb_agg(c #>> '{after,id}' ORDER BY c #>> '{after,id}') FROM jsonb_array_elements(v_changes) c
             WHERE jsonb_array_length(workhub_private.t2_closed_days(p_ctx.school_id, workhub_private.t2_day((c #>> '{after,time,startsAt}')::timestamptz, v_tz),
                                                                     workhub_private.t2_day((c #>> '{after,time,startsAt}')::timestamptz, v_tz) + 1)) > 0);
  IF v_bad IS NOT NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code', 'SCHOOL_CLOSED', 'message', '옮길 날짜가 휴업일입니다.', 'lessonIds', v_bad));
  END IF;
  PERFORM workhub_private.t3_exchange_guard(p_ctx,v_changes);
  RETURN jsonb_build_object('changes', v_changes, 'blockers', v_blockers, 'participants', workhub_private.t2_participants(v_changes));
END $function$

CREATE OR REPLACE FUNCTION workhub_private.t2_school_day_execute(p_ctx workhub_private.actor_context, c jsonb, p_key text, p_recover boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_hash text := workhub_private.p2_sha(c); v jsonb; p workhub.timetable_previews; x jsonb; v_at timestamptz; v_id text; v_ids jsonb;
BEGIN
  v := workhub_private.t2_claim(p_ctx, 'school_day', p_key, v_hash);
  IF v IS NOT NULL THEN RETURN v; END IF;
  IF p_recover IS NULL THEN RAISE EXCEPTION 'INVALID_INPUT'; END IF;
  IF p_recover THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF NOT workhub_private.t2_ready(p_ctx.school_id) THEN RAISE EXCEPTION 'NOT_READY'; END IF;
  IF NOT workhub_private.p2_exact(c, ARRAY['kind','preview']) OR c ->> 'kind' IS DISTINCT FROM 'school_day' OR jsonb_typeof(c -> 'kind') <> 'string'
     OR NOT workhub_private.p2_exact(c -> 'preview', ARRAY['previewId','previewHash','expiresAt']) OR NOT workhub_private.p7_id(c #> '{preview,previewId}')
     OR NOT workhub_private.p5_hash(c #> '{preview,previewHash}') OR workhub_private.t2_parse_ts(c #> '{preview,expiresAt}', false) IS NULL THEN
    RAISE EXCEPTION 'INVALID_INPUT';
  END IF;
  IF NOT workhub_private.p5_manager(p_ctx) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  SELECT * INTO p FROM workhub.timetable_previews WHERE id = c #>> '{preview,previewId}' AND school_id = p_ctx.school_id
     AND membership_id = p_ctx.membership_id AND account_id = p_ctx.account_id AND kind = 'school_day';
  IF p.id IS NULL OR p.preview_hash <> c #>> '{preview,previewHash}' OR to_jsonb(workhub_private.t2_ts(p.expires_at)) <> c #> '{preview,expiresAt}' THEN
    RAISE EXCEPTION 'CONFLICT';
  END IF;
  IF p.expires_at <= clock_timestamp() THEN RAISE EXCEPTION 'CONFLICT'; END IF;
  PERFORM workhub_private.t2_lock(p_ctx.school_id);
  x := workhub_private.t2_school_day_calc(p_ctx, p.input -> 'input', p.source_as_of,
         workhub_private.t2_range(p.input ->> 'from', p.input ->> 'until', workhub_private.t2_limit('listDays')), p.id, p.created_at, p.expires_at);
  IF x ->> 'previewHash' <> p.preview_hash THEN RAISE EXCEPTION 'CONFLICT'; END IF;
  IF jsonb_array_length(x -> 'blockers') > 0 OR jsonb_array_length(x -> 'changes') = 0 THEN RAISE EXCEPTION 'INVALID_INPUT'; END IF;
  v_at := workhub_private.t2_now();
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(x -> 'changes') ch WHERE (ch #>> '{before,time,startsAt}')::timestamptz <= v_at
               OR (ch #>> '{after,state}' <> 'cancelled' AND (ch #>> '{after,time,startsAt}')::timestamptz <= v_at)) THEN
    RAISE EXCEPTION 'CONFLICT';
  END IF;
  v_ids := (SELECT jsonb_agg(jsonb_build_object('id', ch #>> '{after,id}', 'version', ch #> '{after,version}') ORDER BY ch #>> '{after,id}' COLLATE "C")
              FROM jsonb_array_elements(x -> 'changes') ch);
  INSERT INTO workhub.timetable_school_day_changes (school_id, preview_id, input, changed_lessons, lost_lesson_count, membership_id, request_key, recorded_at)
  VALUES (p_ctx.school_id, p.id, p.input -> 'input', v_ids, (x -> 'lostLessonCount')::integer, p_ctx.membership_id, p_key, v_at)
  RETURNING id INTO v_id;
  UPDATE workhub.timetable_lessons l SET state = ch #>> '{after,state}', starts_at = (ch #>> '{after,time,startsAt}')::timestamptz,
         ends_at = (ch #>> '{after,time,endsAt}')::timestamptz, version = (ch #>> '{after,version}')::integer, pinned = true,
         changed_by = 'school_day', changed_at = v_at
    FROM jsonb_array_elements(x -> 'changes') ch WHERE l.school_id = p_ctx.school_id AND l.id = ch #>> '{after,id}';
  INSERT INTO workhub.timetable_lesson_versions (school_id, lesson_id, version, change_kind, source_id, snapshot)
  SELECT l.school_id, l.id, l.version, 'school_day', v_id, to_jsonb(l) - 'school_id'
    FROM workhub.timetable_lessons l JOIN jsonb_array_elements(x -> 'changes') ch ON ch #>> '{after,id}' = l.id WHERE l.school_id = p_ctx.school_id;
  PERFORM workhub_private.write_audit(p_ctx, 'timetable.school_day', 'timetable_school_day_change', v_id, 1, 'school', p_key,
    jsonb_build_object('kind', p.input #>> '{input,kind}', 'date', p.input #>> '{input,date}', 'changes', jsonb_array_length(v_ids),
                       'lostLessonCount', x -> 'lostLessonCount'));
  v := jsonb_build_object('requestKey', p_key, 'commandHash', v_hash, 'kind', 'school_day', 'entityId', v_id, 'version', 1, 'status', 'applied',
                          'recordedAt', workhub_private.t2_ts(v_at), 'changedLessonCount', jsonb_array_length(v_ids), 'changesHash', workhub_private.p2_sha(v_ids),
                          'lostLessonCount', x -> 'lostLessonCount');
  PERFORM workhub_private.t2_record(p_ctx, 'school_day', p_key, v_hash, v);
  RETURN v;
END $function$

CREATE OR REPLACE FUNCTION workhub_private.t2_publish_commit(p_ctx workhub_private.actor_context, p_kind text, p_preview text, p_preview_hash text, p_expires jsonb, i jsonb, p_manifest_hash text, p_basis_fp text, p_total jsonb, p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r workhub.timetable_previews; v_plan jsonb; v_at timestamptz; v_m jsonb; v_pub text;
BEGIN
  IF NOT workhub_private.p5_manager(p_ctx) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  SELECT * INTO r FROM workhub.timetable_previews WHERE id = p_preview AND school_id = p_ctx.school_id AND membership_id = p_ctx.membership_id
     AND account_id = p_ctx.account_id AND kind = p_kind;
  IF r.id IS NULL OR r.preview_hash <> p_preview_hash OR to_jsonb(workhub_private.t2_ts(r.expires_at)) <> p_expires OR r.input <> i
     OR (p_kind = 'manifest' AND (r.manifest_hash <> p_manifest_hash OR to_jsonb(r.total_changes) <> p_total)) THEN
    RAISE EXCEPTION 'CONFLICT';
  END IF;
  IF r.expires_at <= clock_timestamp() THEN RAISE EXCEPTION 'CONFLICT'; END IF;
  PERFORM workhub_private.t2_lock(p_ctx.school_id);
  v_plan := workhub_private.t2_publish_plan(p_ctx, i, r.id, r.created_at);
  IF workhub_private.p2_sha(workhub_private.t2_publish_body(i, v_plan)) <> r.preview_hash THEN RAISE EXCEPTION 'CONFLICT'; END IF;
  IF p_kind = 'manifest' THEN
    v_m := workhub_private.t2_manifest_of(r, p_ctx.school_timezone, v_plan);
    IF v_m ->> 'manifestHash' <> r.manifest_hash OR v_m ->> 'basisFingerprint' <> p_basis_fp THEN RAISE EXCEPTION 'CONFLICT'; END IF;
  END IF;
  IF jsonb_array_length(v_plan -> 'blockers') > 0 OR jsonb_array_length(v_plan -> 'rows') = 0 THEN RAISE EXCEPTION 'INVALID_INPUT'; END IF;
  v_at := workhub_private.t2_now();
  -- 미리보기 뒤 시작해 버린 수업이 바뀌면(이미 지난 수업) 반영하지 않는다
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_plan -> 'rows') x
              WHERE (x ->> 's')::timestamptz <= v_at OR (x #>> '{before,time,startsAt}')::timestamptz <= v_at) THEN
    RAISE EXCEPTION 'CONFLICT';
  END IF;
  v_pub := workhub_private.t2_publish_apply(p_ctx, v_plan, r.id, p_key, v_at);
  PERFORM workhub_private.write_audit(p_ctx, 'timetable.publish', 'timetable_publication', v_pub, 1, 'school', p_key,
    jsonb_build_object('draftId', v_plan ->> 'draftId', 'from', v_plan ->> 'from', 'until', v_plan ->> 'until', 'changes', jsonb_array_length(v_plan -> 'rows'),
                       'previewId', r.id));
  RETURN jsonb_build_object('publicationId', v_pub, 'recordedAt', v_at, 'plan', v_plan, 'manifest', v_m);
END $function$

CREATE OR REPLACE FUNCTION workhub_private.t2_recommend(p_ctx workhub_private.actor_context, i jsonb, p_as_of text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_at timestamptz := workhub_private.t2_parse_ts(to_jsonb(p_as_of), false); v_range daterange; a workhub.timetable_lessons; va jsonb; v_now timestamptz;
        v_tz text := p_ctx.school_timezone; opt record; cand jsonb; x jsonb; r workhub.timetable_previews; v_cands jsonb := '[]'::jsonb; n integer := 0;
        v_limited boolean := false; v_label text;
BEGIN
  IF NOT workhub_private.t2_ready(p_ctx.school_id) THEN RAISE EXCEPTION 'NOT_READY'; END IF;
  IF NOT workhub_private.p2_exact(i, ARRAY['lessonId','expectedVersion','reason','from','until']) OR NOT workhub_private.p7_id(i -> 'lessonId')
     OR NOT workhub_private.p7_pos(i -> 'expectedVersion') OR NOT workhub_private.p7_text(i -> 'reason', workhub_private.t2_limit('reason'), true)
     OR jsonb_typeof(i -> 'from') <> 'string' OR jsonb_typeof(i -> 'until') <> 'string' OR v_at IS NULL OR v_at > clock_timestamp() + interval '30 seconds' THEN
    RAISE EXCEPTION 'INVALID_INPUT';
  END IF;
  v_range := workhub_private.t2_range(i ->> 'from', i ->> 'until', workhub_private.t2_limit('listDays'));
  IF NOT workhub_private.t2_unchanged(p_ctx.school_id, v_at, v_range, v_tz) THEN RAISE EXCEPTION 'CONFLICT'; END IF;
  v_now := workhub_private.t2_now();
  SELECT * INTO a FROM workhub.timetable_lessons WHERE school_id = p_ctx.school_id AND id = i ->> 'lessonId';
  IF a.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF NOT (p_ctx.membership_id = ANY (a.teacher_ids)) OR a.changed_by = 'school_day' OR workhub_private.t2_lesson_busy(a.school_id, a.id, v_now) THEN
    RAISE EXCEPTION 'FORBIDDEN';
  END IF;
  IF to_jsonb(a.version) <> i -> 'expectedVersion' OR a.state <> 'scheduled' OR a.starts_at <= v_now THEN RAISE EXCEPTION 'CONFLICT'; END IF;
  va := workhub_private.t2_vlesson(a, p_ctx, v_now);
  -- 후보 순서: 빈 시간으로 옮기기(시각 순) → 맞바꾸기(시각 순). 40개까지 살펴본다.
  FOR opt IN
    SELECT 1 AS ord, (t ->> 'startsAt')::timestamptz AS s, jsonb_build_object('kind', 'move', 'lessonId', a.id, 'expectedVersion', a.version, 'target', t,
             'reason', i -> 'reason') AS inp, NULL::text AS other_label
      FROM jsonb_array_elements(va -> 'allowedTargets') t
     WHERE t <> va -> 'time' AND (t ->> 'startsAt')::timestamptz > v_now
       AND workhub_private.t2_in((t ->> 'startsAt')::timestamptz, (t ->> 'endsAt')::timestamptz, v_range, v_tz)
    UNION ALL
    SELECT 2, o.starts_at, jsonb_build_object('kind', 'swap', 'lessonId', a.id, 'expectedVersion', a.version, 'otherLessonId', o.id,
             'otherExpectedVersion', o.version, 'reason', i -> 'reason'), o.label
      FROM workhub.timetable_lessons o
     WHERE o.school_id = a.school_id AND o.id <> a.id AND o.state = 'scheduled' AND o.changed_by <> 'school_day' AND o.starts_at > v_now
       AND (va -> 'allowedTargets') @> jsonb_build_array(workhub_private.t2_time(o.starts_at, o.ends_at))
       AND workhub_private.t2_in(o.starts_at, o.ends_at, v_range, v_tz) AND workhub_private.t2_in(a.starts_at, a.ends_at, v_range, v_tz)
       AND workhub_private.t2_targets(o, v_tz) @> jsonb_build_array(va -> 'time')
    ORDER BY 1, 2, 3
  LOOP
    IF n >= 40 THEN v_limited := true; EXIT; END IF;
    n := n + 1;
    BEGIN
      x := workhub_private.t2_exchange_calc(p_ctx, opt.inp, v_now);
    EXCEPTION WHEN raise_exception THEN
      IF workhub_private.p7_business(SQLERRM) THEN CONTINUE; END IF;
      RAISE;
    END;
    IF jsonb_array_length(x -> 'blockers') > 0 THEN CONTINUE; END IF;
    r := workhub_private.t2_preview_row(p_ctx, 'exchange', opt.inp, NULL);
    r.created_at := v_now; r.expires_at := v_now + make_interval(secs => workhub_private.t2_limit('previewLifetimeMs') / 1000.0);
    cand := workhub_private.t2_exchange_store(p_ctx, opt.inp, x, r);
    v_label := to_char((x #>> '{changes,0,after,time,startsAt}')::timestamptz AT TIME ZONE v_tz, 'MM/DD HH24:MI');
    v_cands := v_cands || jsonb_build_array(jsonb_build_object('id', 'c' || (jsonb_array_length(v_cands) + 1), 'input', opt.inp, 'preview', cand,
      'explanation', CASE WHEN opt.ord = 1 THEN format('같은 주의 빈 시간(%s)으로 옮깁니다.', v_label)
                          ELSE format('%s 수업과 시간을 맞바꿉니다(%s).', workhub_private.t1_label(opt.other_label, 200, '다른'), v_label) END));
    IF jsonb_array_length(v_cands) >= workhub_private.t2_limit('recommendations') THEN EXIT; END IF;
  END LOOP;
  RETURN jsonb_build_object('input', i, 'sourceAsOf', p_as_of,
    'coverage', jsonb_build_object('from', i -> 'from', 'until', i -> 'until', 'complete', true),
    'status', CASE WHEN jsonb_array_length(v_cands) > 0 THEN 'candidates' WHEN v_limited THEN 'search_limited' ELSE 'none_found' END,
    'explanations', CASE WHEN jsonb_array_length(v_cands) > 0 THEN jsonb_build_array('같은 주 안에서 이 수업이 들어갈 수 있는 공식 시간대만 찾았습니다. 제출 전 관련 교사 동의와 승인이 필요합니다.')
                         WHEN v_limited THEN jsonb_build_array('살펴본 시간대 40개 안에서는 막히지 않는 후보를 찾지 못했습니다. 직접 시간을 골라 확인해 주세요.')
                         ELSE jsonb_build_array('같은 주 안에서 겹치지 않고 옮기거나 맞바꿀 수 있는 시간을 찾지 못했습니다.') END,
    'candidates', v_cands);
END $function$

CREATE OR REPLACE FUNCTION workhub_private.t2_action(p_ctx workhub_private.actor_context, c jsonb, p_key text, p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE rq workhub.timetable_exchange_requests; v_at timestamptz; v_act text := c ->> 'action'; v_status text; v_changed jsonb := '[]'::jsonb; v_c text[];
        v_tz text := p_ctx.school_timezone; v_others text[];
BEGIN
  IF NOT workhub_private.p2_exact(c, ARRAY['kind','requestId','expectedVersion','proposalHash','action']) OR NOT workhub_private.p7_id(c -> 'requestId')
     OR NOT workhub_private.p7_pos(c -> 'expectedVersion') OR NOT workhub_private.p5_hash(c -> 'proposalHash') OR jsonb_typeof(c -> 'action') <> 'string'
     OR v_act NOT IN ('accept','reject','withdraw','approve','rejectApproval') THEN
    RAISE EXCEPTION 'INVALID_INPUT';
  END IF;
  PERFORM workhub_private.t2_lock(p_ctx.school_id);
  SELECT * INTO rq FROM workhub.timetable_exchange_requests WHERE school_id = p_ctx.school_id AND id = c ->> 'requestId' FOR UPDATE;
  IF rq.id IS NULL OR NOT workhub_private.t2_req_visible(rq, p_ctx) THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF to_jsonb(rq.version) <> c -> 'expectedVersion' OR rq.proposal_hash <> c ->> 'proposalHash' THEN RAISE EXCEPTION 'CONFLICT'; END IF;
  IF EXISTS(SELECT 1 FROM workhub.timetable_intervention_policies WHERE school_id=p_ctx.school_id) THEN PERFORM workhub_private.t3_lock_members(p_ctx.school_id);END IF;
  PERFORM workhub_private.t3_exchange_guard(p_ctx,rq.changes,v_act IN ('approve','rejectApproval'),rq.requester_account_id);
  v_at := workhub_private.t2_now();
  -- 끝났거나 · 기한이 지났거나 · 수업 판이 바뀐 요청은 응답할 수 없다
  IF rq.state NOT IN ('awaiting_consent','awaiting_approval') OR rq.expires_at <= v_at OR workhub_private.t2_req_stale(rq.id) THEN RAISE EXCEPTION 'CONFLICT'; END IF;
  v_others := ARRAY(SELECT membership_id FROM workhub.timetable_exchange_participants WHERE request_id = rq.id AND membership_id <> rq.requester_membership_id
                     ORDER BY membership_id);
  IF v_act IN ('accept','reject') THEN
    IF rq.state <> 'awaiting_consent' OR NOT EXISTS (SELECT 1 FROM workhub.timetable_exchange_participants
                                                     WHERE request_id = rq.id AND membership_id = p_ctx.membership_id AND response = 'pending') THEN
      RAISE EXCEPTION 'FORBIDDEN';
    END IF;
    UPDATE workhub.timetable_exchange_participants SET response = CASE WHEN v_act = 'accept' THEN 'accepted' ELSE 'rejected' END, responded_at = v_at
     WHERE request_id = rq.id AND membership_id = p_ctx.membership_id;
    IF v_act = 'reject' THEN v_status := 'rejected';
    ELSIF NOT EXISTS (SELECT 1 FROM workhub.timetable_exchange_participants WHERE request_id = rq.id AND response <> 'accepted') THEN v_status := 'awaiting_approval';
    ELSE v_status := 'awaiting_consent'; END IF;
  ELSIF v_act = 'withdraw' THEN
    IF rq.requester_account_id <> p_ctx.account_id THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
    v_status := 'withdrawn';
  ELSE
    IF rq.state <> 'awaiting_approval' OR NOT workhub_private.p5_manager(p_ctx) OR rq.requester_account_id = p_ctx.account_id
       OR EXISTS (SELECT 1 FROM workhub.timetable_exchange_participants WHERE request_id = rq.id AND response <> 'accepted') THEN
      RAISE EXCEPTION 'FORBIDDEN';
    END IF;
    IF v_act = 'rejectApproval' THEN
      v_status := 'rejected';
    ELSE
      -- 반영 직전 다시 확인: 시작 전 · 자원 겹침 · 불가 조건 · 휴업일
      IF EXISTS (SELECT 1 FROM jsonb_array_elements(rq.changes) ch WHERE (ch #>> '{before,time,startsAt}')::timestamptz <= v_at
                                                                     OR (ch #>> '{after,time,startsAt}')::timestamptz <= v_at) THEN
        RAISE EXCEPTION 'CONFLICT';
      END IF;
      v_c := workhub_private.t2_conflicts(p_ctx.school_id, (
        SELECT jsonb_agg(jsonb_build_object('id', l.id, 's', ch #>> '{after,time,startsAt}', 'e', ch #>> '{after,time,endsAt}', 'uses', l.uses))
          FROM jsonb_array_elements(rq.changes) ch JOIN workhub.timetable_lessons l ON l.school_id = rq.school_id AND l.id = ch #>> '{after,id}'), ARRAY[]::text[]);
      IF cardinality(v_c) > 0 OR EXISTS (
           SELECT 1 FROM jsonb_array_elements(rq.changes) ch JOIN workhub.timetable_lessons l ON l.school_id = rq.school_id AND l.id = ch #>> '{after,id}'
            WHERE workhub_private.t2_unavailable(l.publication_id, l.uses, (ch #>> '{after,time,startsAt}')::timestamptz, (ch #>> '{after,time,endsAt}')::timestamptz, v_tz)
               OR jsonb_array_length(workhub_private.t2_closed_days(rq.school_id, workhub_private.t2_day((ch #>> '{after,time,startsAt}')::timestamptz, v_tz),
                                                                    workhub_private.t2_day((ch #>> '{after,time,startsAt}')::timestamptz, v_tz) + 1)) > 0) THEN
        RAISE EXCEPTION 'CONFLICT';
      END IF;
      UPDATE workhub.timetable_lessons l SET starts_at = (ch #>> '{after,time,startsAt}')::timestamptz, ends_at = (ch #>> '{after,time,endsAt}')::timestamptz,
             version = (ch #>> '{after,version}')::integer, pinned = true, changed_by = 'exchange', changed_at = v_at
        FROM jsonb_array_elements(rq.changes) ch WHERE l.school_id = rq.school_id AND l.id = ch #>> '{after,id}';
      INSERT INTO workhub.timetable_lesson_versions (school_id, lesson_id, version, change_kind, source_id, snapshot)
      SELECT l.school_id, l.id, l.version, 'exchange', rq.id, to_jsonb(l) - 'school_id'
        FROM workhub.timetable_lessons l JOIN jsonb_array_elements(rq.changes) ch ON ch #>> '{after,id}' = l.id WHERE l.school_id = rq.school_id;
      v_changed := (SELECT jsonb_agg(jsonb_build_object('id', ch #>> '{after,id}', 'version', ch #> '{after,version}') ORDER BY o)
                      FROM jsonb_array_elements(rq.changes) WITH ORDINALITY z(ch, o));
      v_status := 'applied';
    END IF;
  END IF;
  UPDATE workhub.timetable_exchange_requests SET state = v_status, version = version + 1, updated_at = v_at,
         decided_by_membership_id = CASE WHEN v_act IN ('approve','rejectApproval') THEN p_ctx.membership_id ELSE decided_by_membership_id END
   WHERE id = rq.id RETURNING * INTO rq;
  -- 알림(같은 트랜잭션)
  IF v_act = 'accept' AND v_status = 'awaiting_approval' THEN
    PERFORM workhub_private.t2_notify(rq, workhub_private.t2_approver_ids(rq, p_ctx.school_today), 'approval', '시간표 변경 승인 요청',
                                      workhub_private.t2_req_summary(rq, v_tz) || '. 관련 교사가 모두 동의했습니다. 승인 또는 반려해 주세요.');
  ELSIF v_status = 'rejected' THEN
    PERFORM workhub_private.t2_notify(rq, ARRAY[rq.requester_membership_id], 'rejected', '시간표 변경 요청이 거절되었습니다',
                                      workhub_private.t2_req_summary(rq, v_tz) || CASE WHEN v_act = 'reject' THEN '. 관련 교사가 거절했습니다.' ELSE '. 승인 담당이 반려했습니다.' END);
  ELSIF v_status = 'withdrawn' THEN
    PERFORM workhub_private.t2_notify(rq, v_others, 'withdrawn', '시간표 변경 요청이 철회되었습니다', workhub_private.t2_req_summary(rq, v_tz) || '. 요청한 선생님이 철회했습니다.');
  ELSIF v_status = 'applied' THEN
    PERFORM workhub_private.t2_notify(rq, ARRAY[rq.requester_membership_id] || v_others, 'applied', '시간표 변경이 반영되었습니다',
                                      workhub_private.t2_req_summary(rq, v_tz) || '. 공개 시간표에 반영했습니다.');
  END IF;
  PERFORM workhub_private.write_audit(p_ctx, 'timetable.exchange_' || lower(v_act), 'timetable_exchange_request', rq.id, rq.version, 'school', p_key,
    jsonb_build_object('state', v_status));
  RETURN jsonb_build_object('requestKey', p_key, 'commandHash', p_hash, 'kind', 'action', 'entityId', rq.id, 'version', rq.version, 'status', v_status,
                            'recordedAt', workhub_private.t2_ts(v_at), 'changedLessons', v_changed);
END $function$

CREATE OR REPLACE FUNCTION workhub_private.t2_submit(p_ctx workhub_private.actor_context, c jsonb, p_key text, p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p workhub.timetable_previews; x jsonb; v_at timestamptz; rq workhub.timetable_exchange_requests; v_changes jsonb; v_all text[]; v_tz text := p_ctx.school_timezone;
BEGIN
  PERFORM workhub_private.t2_exchange_input(c #> '{preview,input}');
  SELECT * INTO p FROM workhub.timetable_previews WHERE id = c #>> '{preview,previewId}' AND school_id = p_ctx.school_id
     AND membership_id = p_ctx.membership_id AND account_id = p_ctx.account_id AND kind = 'exchange';
  IF p.id IS NULL OR p.preview_hash <> c #>> '{preview,previewHash}' OR to_jsonb(workhub_private.t2_ts(p.expires_at)) <> c #> '{preview,expiresAt}'
     OR p.input <> c #> '{preview,input}' THEN
    RAISE EXCEPTION 'CONFLICT';
  END IF;
  IF p.expires_at <= clock_timestamp() THEN RAISE EXCEPTION 'CONFLICT'; END IF;
  PERFORM workhub_private.t2_lock(p_ctx.school_id);
  IF EXISTS(SELECT 1 FROM workhub.timetable_intervention_policies WHERE school_id=p_ctx.school_id) THEN PERFORM workhub_private.t3_lock_members(p_ctx.school_id);END IF;
  x := workhub_private.t2_exchange_calc(p_ctx, p.input, p.created_at);
  IF workhub_private.p2_sha(workhub_private.t2_exchange_body(p.input, x)) <> p.preview_hash THEN RAISE EXCEPTION 'CONFLICT'; END IF;
  IF jsonb_array_length(x -> 'blockers') > 0 THEN RAISE EXCEPTION 'INVALID_INPUT'; END IF;
  v_at := workhub_private.t2_now();
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(x -> 'changes') ch WHERE (ch #>> '{before,time,startsAt}')::timestamptz <= v_at
                                                                     OR (ch #>> '{after,time,startsAt}')::timestamptz <= v_at)
     OR EXISTS (SELECT 1 FROM jsonb_array_elements(x -> 'changes') ch WHERE workhub_private.t2_lesson_busy(p_ctx.school_id, ch #>> '{after,id}', v_at)) THEN
    RAISE EXCEPTION 'CONFLICT';
  END IF;
  -- 요청에 고정하는 값: 요청 버튼은 끈다(전후 같은 값). 동의는 이 값의 지문(proposalHash)에 묶인다.
  v_changes := (SELECT jsonb_agg(jsonb_build_object('before', ch -> 'before' || '{"canRequest":false}'::jsonb,
                                                    'after', ch -> 'after' || '{"canRequest":false}'::jsonb) ORDER BY o)
                  FROM jsonb_array_elements(x -> 'changes') WITH ORDINALITY z(ch, o));
  v_all := ARRAY(SELECT t ->> 'id' FROM jsonb_array_elements(x -> 'participants') t);
  rq.id := gen_random_uuid()::text; rq.school_id := p_ctx.school_id; rq.kind := p.input ->> 'kind';
  rq.requester_membership_id := p_ctx.membership_id; rq.requester_account_id := p_ctx.account_id;
  rq.requester_name := (SELECT t ->> 'name' FROM jsonb_array_elements(x -> 'participants') t WHERE t ->> 'id' = p_ctx.membership_id);
  rq.reason := p.input ->> 'reason'; rq.changes := v_changes;
  rq.proposal_hash := workhub_private.p2_sha(jsonb_build_object('kind', rq.kind, 'reason', rq.reason, 'changes', v_changes));
  SELECT min(workhub_private.t2_day(t, v_tz)), max(workhub_private.t2_day(t, v_tz)), min(t) INTO rq.first_day, rq.last_day, rq.expires_at
    FROM (SELECT (ch #>> '{before,time,startsAt}')::timestamptz AS t FROM jsonb_array_elements(v_changes) ch
          UNION ALL SELECT (ch #>> '{after,time,startsAt}')::timestamptz FROM jsonb_array_elements(v_changes) ch) z;
  rq.state := CASE WHEN v_all <@ ARRAY[p_ctx.membership_id] THEN 'awaiting_approval' ELSE 'awaiting_consent' END;
  rq.version := 1; rq.preview_id := p.id; rq.created_at := v_at; rq.updated_at := v_at;
  INSERT INTO workhub.timetable_exchange_requests SELECT rq.*;
  INSERT INTO workhub.timetable_exchange_lessons (school_id, request_id, lesson_id, before_version)
  SELECT p_ctx.school_id, rq.id, ch #>> '{before,id}', (ch #>> '{before,version}')::integer FROM jsonb_array_elements(v_changes) ch;
  INSERT INTO workhub.timetable_exchange_participants (school_id, request_id, membership_id, name, response, responded_at)
  SELECT p_ctx.school_id, rq.id, t ->> 'id', t ->> 'name', CASE WHEN t ->> 'id' = p_ctx.membership_id THEN 'accepted' ELSE 'pending' END,
         CASE WHEN t ->> 'id' = p_ctx.membership_id THEN v_at END
    FROM jsonb_array_elements(x -> 'participants') t;
  IF rq.state = 'awaiting_consent' THEN
    PERFORM workhub_private.t2_notify(rq, array_remove(v_all, p_ctx.membership_id), 'consent', '시간표 변경 동의 요청',
                                      workhub_private.t2_req_summary(rq, v_tz) || '. 동의 또는 거절해 주세요.');
  ELSE
    PERFORM workhub_private.t2_notify(rq, workhub_private.t2_approver_ids(rq, p_ctx.school_today), 'approval', '시간표 변경 승인 요청',
                                      workhub_private.t2_req_summary(rq, v_tz) || '. 승인 또는 반려해 주세요.');
  END IF;
  PERFORM workhub_private.write_audit(p_ctx, 'timetable.exchange_submit', 'timetable_exchange_request', rq.id, 1, 'school', p_key,
    jsonb_build_object('kind', rq.kind, 'lessons', (SELECT jsonb_agg(ch #>> '{before,id}') FROM jsonb_array_elements(v_changes) ch), 'state', rq.state));
  RETURN jsonb_build_object('requestKey', p_key, 'commandHash', p_hash, 'kind', 'submit', 'entityId', rq.id, 'version', 1, 'status', rq.state,
                            'recordedAt', workhub_private.t2_ts(v_at), 'changedLessons', '[]'::jsonb);
END $function$

CREATE OR REPLACE FUNCTION workhub_private.t2_exec_record(p_ctx workhub_private.actor_context, c jsonb, p_key text, p_recover boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_hash text := workhub_private.p2_sha(c); v jsonb; l workhub.timetable_lessons; r workhub.timetable_execution_records;
        v_at timestamptz; v_ver integer; n workhub.timetable_execution_record_versions;
BEGIN
  v := workhub_private.t2_claim(p_ctx, 'execution', p_key, v_hash);
  IF v IS NOT NULL THEN RETURN v; END IF;
  IF p_recover IS NULL THEN RAISE EXCEPTION 'INVALID_INPUT'; END IF;
  IF p_recover THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF NOT workhub_private.t2_ready(p_ctx.school_id) THEN RAISE EXCEPTION 'NOT_READY'; END IF;
  PERFORM workhub_private.t2_exec_command(c);
  -- 공개 · 교환 · 학사 변경과 같은 학교 잠금(수업 판이 그 사이 바뀌지 않게)
  PERFORM workhub_private.t2_lock(p_ctx.school_id);
  SELECT * INTO l FROM workhub.timetable_lessons WHERE school_id = p_ctx.school_id AND id = c ->> 'lessonId' FOR UPDATE;
  IF l.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF NOT p_ctx.membership_id = ANY (l.teacher_ids) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  v_at := workhub_private.t2_now();
  IF l.ends_at > v_at THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  IF l.state <> 'scheduled' OR l.version <> (c ->> 'expectedLessonVersion')::integer THEN RAISE EXCEPTION 'CONFLICT'; END IF;
  SELECT * INTO r FROM workhub.timetable_execution_records WHERE school_id = p_ctx.school_id AND lesson_id = l.id FOR UPDATE;
  IF COALESCE(r.version, 0) <> (c ->> 'expectedRecordVersion')::integer OR r.id IS DISTINCT FROM (c ->> 'expectedRecordId') THEN
    RAISE EXCEPTION 'CONFLICT';
  END IF;
  IF r.id IS NULL THEN
    INSERT INTO workhub.timetable_execution_records (school_id, lesson_id, version, updated_at) VALUES (p_ctx.school_id, l.id, 1, v_at) RETURNING * INTO r;
  ELSE
    UPDATE workhub.timetable_execution_records SET version = version + 1, updated_at = v_at WHERE id = r.id RETURNING * INTO r;
  END IF;
  INSERT INTO workhub.timetable_execution_record_versions (school_id, record_id, version, lesson_id, lesson_version, outcome, note, correction_reason,
                                                          recorded_by_membership_id, recorded_by_name, request_key, recorded_at)
  VALUES (p_ctx.school_id, r.id, r.version, l.id, l.version, c ->> 'outcome', c ->> 'note', c ->> 'correctionReason',
          p_ctx.membership_id, workhub_private.t2_member_name(p_ctx.membership_id), p_key, v_at)
  RETURNING * INTO n;
  -- 감사에는 메모 · 사유 원문을 넣지 않는다(결과와 판만)
  PERFORM workhub_private.write_audit(p_ctx, CASE WHEN r.version = 1 THEN 'timetable.execution_record' ELSE 'timetable.execution_correct' END,
    'timetable_execution_record', r.id, r.version, 'school', p_key,
    jsonb_build_object('lessonId', l.id, 'lessonVersion', l.version, 'outcome', c ->> 'outcome'));
  v := jsonb_build_object('requestKey', p_key, 'commandHash', v_hash, 'record', workhub_private.t2_exec_row(n));
  PERFORM workhub_private.t2_record(p_ctx, 'execution', p_key, v_hash, v);
  RETURN v;
END $function$

CREATE OR REPLACE FUNCTION workhub_private.t2_req_view(r workhub.timetable_exchange_requests, p_ctx workhub_private.actor_context, p_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_state text; v_parts jsonb; v_all boolean; v_viewer boolean := r.requester_account_id = p_ctx.account_id; v_actions jsonb := '[]'::jsonb;
BEGIN
  v_state := CASE WHEN r.state NOT IN ('awaiting_consent','awaiting_approval') THEN r.state WHEN r.expires_at <= p_at THEN 'expired'
                  WHEN workhub_private.t2_req_stale(r.id) THEN 'stale' ELSE r.state END;
  SELECT jsonb_agg(jsonb_build_object('id', p.membership_id, 'name', p.name, 'response', p.response,
                                      'respondedAt', CASE WHEN p.responded_at IS NULL THEN 'null'::jsonb ELSE to_jsonb(workhub_private.t2_ts(p.responded_at)) END)
                   ORDER BY p.membership_id), bool_and(p.response = 'accepted')
    INTO v_parts, v_all FROM workhub.timetable_exchange_participants p WHERE p.request_id = r.id;
  IF v_state = 'awaiting_consent' AND EXISTS (SELECT 1 FROM workhub.timetable_exchange_participants p
                                              WHERE p.request_id = r.id AND p.membership_id = p_ctx.membership_id AND p.response = 'pending') THEN
    v_actions := v_actions || '["accept","reject"]'::jsonb;
  END IF;
  IF v_state IN ('awaiting_consent','awaiting_approval') AND v_viewer THEN v_actions := v_actions || '["withdraw"]'::jsonb; END IF;
  IF v_state = 'awaiting_approval' AND v_all AND NOT v_viewer AND workhub_private.p5_manager(p_ctx) THEN
    v_actions := v_actions || '["approve","rejectApproval"]'::jsonb;
  END IF;
  IF EXISTS(SELECT 1 FROM workhub.timetable_intervention_policies WHERE school_id=p_ctx.school_id) THEN
    IF workhub_private.t3_ready(p_ctx) IS NOT NULL THEN v_actions:='[]';
    ELSIF EXISTS(SELECT 1 FROM workhub.timetable_exchange_participants p JOIN workhub.memberships m ON m.school_id=p.school_id AND m.id=p.membership_id WHERE p.request_id=r.id AND m.account_id=p_ctx.account_id) THEN v_actions:=v_actions-'approve'-'rejectApproval';END IF;
  END IF;
  RETURN jsonb_build_object('id', r.id, 'version', r.version, 'proposalHash', r.proposal_hash, 'state', v_state, 'kind', r.kind,
    'requester', jsonb_build_object('id', r.requester_membership_id, 'name', r.requester_name), 'requesterIsViewer', v_viewer,
    'createdAt', workhub_private.t2_ts(r.created_at), 'expiresAt', workhub_private.t2_ts(r.expires_at), 'reason', r.reason,
    'changes', r.changes, 'participants', COALESCE(v_parts, '[]'::jsonb), 'actions', v_actions);
END $function$

CREATE OR REPLACE FUNCTION workhub_private.t3_execute(ctx workhub_private.actor_context, c jsonb, p_key text, p_recover boolean, p_close boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE old workhub.timetable_intervention_commands;p workhub.timetable_intervention_previews;r workhub.timetable_interventions;
 h text;x jsonb;receipt jsonb;at timestamptz;changed jsonb:='[]';action text;cstate text;ids text[];
BEGIN
 PERFORM workhub_private.t3_command(c);
 IF NOT workhub_private.p7_key(p_key) OR p_recover IS NULL OR p_close IS NULL THEN RAISE EXCEPTION 'INVALID_INPUT';END IF;
 h:=workhub_private.p2_sha(c);
 -- 닫기와 실행은 같은 학교 잠금 안에서 원키를 확인한다. 모듈 중지·미리보기 만료보다 접수증이 먼저다.
 PERFORM workhub_private.t2_lock(ctx.school_id);
 SELECT * INTO old FROM workhub.timetable_intervention_commands WHERE school_id=ctx.school_id AND membership_id=ctx.membership_id AND request_key=p_key;
 IF old.request_key IS NOT NULL THEN
 IF old.account_id<>ctx.account_id OR old.command_hash<>h THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT';END IF;
 IF p_close THEN RETURN jsonb_build_object('requestKey',p_key,'commandHash',h,'outcome',old.outcome,'receipt',old.receipt,'decidedAt',workhub_private.t2_ts(old.recorded_at));END IF;
 IF old.outcome='closed' THEN RAISE EXCEPTION 'CONFLICT';END IF;
 RETURN old.receipt;END IF;
 IF p_recover THEN RAISE EXCEPTION 'NOT_FOUND';END IF;
 -- 현재 본인 소속을 통과한 사람의 자기 명령만 닫는다. 새 동의·승인은 수행하지 않는다.
 IF p_close THEN
 IF ((c#>>'{preview,input,kind}')='reopen' OR (c->>'kind'='action' AND c->>'action' IN('approve','rejectApproval'))) AND NOT workhub_private.p5_manager(ctx) THEN RAISE EXCEPTION 'FORBIDDEN';END IF;
 IF c->>'kind'='submit' THEN
 SELECT * INTO p FROM workhub.timetable_intervention_previews WHERE id=c#>>'{preview,previewId}' AND school_id=ctx.school_id AND membership_id=ctx.membership_id AND account_id=ctx.account_id;
 IF p.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND';END IF;
 IF p.preview_hash<>c#>>'{preview,previewHash}' OR p.input<>c#>'{preview,input}' OR workhub_private.t2_ts(p.expires_at)<>c#>>'{preview,expiresAt}' THEN RAISE EXCEPTION 'CONFLICT';END IF;
 IF EXISTS(SELECT 1 FROM workhub.timetable_interventions WHERE preview_id=p.id) THEN RAISE EXCEPTION 'CONFLICT';END IF;
 ELSE
 SELECT * INTO r FROM workhub.timetable_interventions WHERE school_id=ctx.school_id AND id=c->>'requestId';
 IF r.id IS NULL OR NOT workhub_private.t3_visible(r,ctx) THEN RAISE EXCEPTION 'NOT_FOUND';END IF;
 END IF;
 INSERT INTO workhub.timetable_intervention_commands(school_id,membership_id,account_id,request_key,command_hash,outcome)
 VALUES(ctx.school_id,ctx.membership_id,ctx.account_id,p_key,h,'closed') RETURNING * INTO old;
 PERFORM workhub_private.write_audit(ctx,'timetable.intervention_close','timetable_intervention_command',p_key,NULL,'school',p_key,'{}');
 RETURN jsonb_build_object('requestKey',p_key,'commandHash',h,'outcome','closed','receipt',NULL,'decidedAt',workhub_private.t2_ts(old.recorded_at));END IF;
 IF workhub_private.t3_ready(ctx) IS NOT NULL THEN RAISE EXCEPTION 'NOT_READY';END IF;
 PERFORM workhub_private.t3_lock_members(ctx.school_id);
 IF workhub_private.t3_ready(ctx) IS NOT NULL THEN RAISE EXCEPTION 'NOT_READY';END IF;
 at:=workhub_private.t2_now();
 IF c->>'kind'='submit' THEN
 SELECT * INTO p FROM workhub.timetable_intervention_previews WHERE id=c#>>'{preview,previewId}' AND school_id=ctx.school_id AND membership_id=ctx.membership_id AND account_id=ctx.account_id;
 IF p.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND';END IF;
 IF p.preview_hash<>c#>>'{preview,previewHash}' OR p.input<>c#>'{preview,input}' OR workhub_private.t2_ts(p.expires_at)<>c#>>'{preview,expiresAt}' OR p.expires_at<=at
 OR EXISTS(SELECT 1 FROM workhub.timetable_interventions z WHERE z.preview_id=p.id) THEN RAISE EXCEPTION 'CONFLICT';END IF;
 x:=workhub_private.t3_plan(ctx,p.input,p.id,p.created_at);
 IF x<>p.plan THEN RAISE EXCEPTION 'CONFLICT';END IF;
 IF jsonb_array_length(x->'blockers')>0 THEN RAISE EXCEPTION 'INVALID_INPUT';END IF;
 -- 시작 직전에 오래된 미리보기를 제출할 수 없다.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(x->'rows') a WHERE (a->>'starts_at')::timestamptz<=at) THEN RAISE EXCEPTION 'CONFLICT';END IF;
 ids:=ARRAY(SELECT a->>'id' FROM jsonb_array_elements(x->'participants') a);
 r.id:=gen_random_uuid()::text;r.school_id:=ctx.school_id;r.kind:=p.input->>'kind';r.requester_membership_id:=ctx.membership_id;r.requester_account_id:=ctx.account_id;
 r.input:=p.input;r.plan:=x;r.proposal_hash:=workhub_private.p2_sha(jsonb_build_object('input',p.input,'plan',x));r.preview_id:=p.id;
 r.state:=CASE WHEN ids<@ARRAY[ctx.membership_id] THEN 'awaiting_approval' ELSE 'awaiting_consent' END;
 r.version:=1;r.created_at:=at;r.updated_at:=at;
 SELECT min((a->>'starts_at')::timestamptz) INTO r.expires_at FROM jsonb_array_elements(x->'rows') a;
 INSERT INTO workhub.timetable_interventions SELECT r.*;
 INSERT INTO workhub.timetable_intervention_participants(school_id,intervention_id,membership_id,response,responded_at)
 SELECT ctx.school_id,r.id,id,CASE WHEN id=ctx.membership_id THEN 'accepted' ELSE 'pending' END,CASE WHEN id=ctx.membership_id THEN at END FROM unnest(ids) id;
 ELSE
 SELECT * INTO r FROM workhub.timetable_interventions WHERE school_id=ctx.school_id AND id=c->>'requestId' FOR UPDATE;
 IF r.id IS NULL OR NOT workhub_private.t3_visible(r,ctx) THEN RAISE EXCEPTION 'NOT_FOUND';END IF;
 IF r.version<>(c->>'expectedVersion')::integer OR r.proposal_hash<>c->>'proposalHash' OR NOT workhub_private.t3_live(r,at) THEN RAISE EXCEPTION 'CONFLICT';END IF;
 action:=c->>'action';
 IF NOT(workhub_private.t3_actions(r,ctx,at) ? action) THEN RAISE EXCEPTION 'FORBIDDEN';END IF;
 IF action IN('accept','reject') THEN
 UPDATE workhub.timetable_intervention_participants SET response=CASE WHEN action='accept' THEN 'accepted' ELSE 'rejected' END,responded_at=at
 WHERE intervention_id=r.id AND membership_id=ctx.membership_id;
 cstate:=CASE WHEN action='reject' THEN 'rejected' WHEN NOT EXISTS(SELECT 1 FROM workhub.timetable_intervention_participants z WHERE z.intervention_id=r.id AND z.response<>'accepted') THEN 'awaiting_approval' ELSE 'awaiting_consent' END;
 ELSIF action='withdraw' THEN cstate:='withdrawn';
 ELSIF action='rejectApproval' THEN cstate:='rejected';
 ELSE
 IF EXISTS(SELECT 1 FROM workhub.timetable_intervention_participants z WHERE z.intervention_id=r.id AND z.response<>'accepted') THEN RAISE EXCEPTION 'FORBIDDEN';END IF;
 -- 원요청자 맥락으로 다시 계산하되 현재 권한은 승인자도 확인한 상태다.
 DECLARE requester workhub_private.actor_context;BEGIN
 requester:=ctx;requester.membership_id:=r.requester_membership_id;requester.account_id:=r.requester_account_id;
 IF NOT workhub_private.t3_member(r.school_id,r.requester_membership_id) THEN RAISE EXCEPTION 'CONFLICT';END IF;
 x:=workhub_private.t3_plan(requester,r.input,r.preview_id,at,r.id);
 END;
 IF jsonb_array_length(x->'blockers')>0 OR x->'sources'<>r.plan->'sources' OR x->'rows'<>r.plan->'rows'
 OR x->'participants'<>r.plan->'participants' OR x->'memberships'<>r.plan->'memberships' OR x->'policy'<>r.plan->'policy' THEN RAISE EXCEPTION 'CONFLICT';END IF;
 cstate:='applied';
 END IF;
 UPDATE workhub.timetable_interventions SET state=cstate,version=version+1,updated_at=at,
 decided_by_membership_id=CASE WHEN action IN('approve','rejectApproval') THEN ctx.membership_id ELSE decided_by_membership_id END WHERE id=r.id RETURNING * INTO r;
 IF cstate='applied' THEN changed:=workhub_private.t3_apply(ctx,r,at);END IF;
 END IF;
 PERFORM workhub_private.t3_record_version(r);
 ids:=ARRAY(SELECT membership_id FROM workhub.timetable_intervention_participants WHERE intervention_id=r.id);
 IF r.state='awaiting_approval' THEN ids:=ids||ARRAY(SELECT membership_id FROM workhub_private.t3_approvers(ctx.school_id,ctx.school_today));END IF;
 ids:=ARRAY(SELECT DISTINCT a FROM unnest(ids||r.requester_membership_id) a);
 PERFORM workhub_private.t3_notify(r,ids,COALESCE(action,'submit'));
 PERFORM workhub_private.write_audit(ctx,'timetable.intervention_'||COALESCE(action,'submit'),'timetable_intervention',r.id,r.version,'school',p_key,jsonb_build_object('kind',r.kind,'state',r.state));
 receipt:=jsonb_build_object('requestKey',p_key,'commandHash',h,'kind',c->>'kind','entityId',r.id,'version',r.version,'status',r.state,'recordedAt',workhub_private.t2_ts(at),'changedLessons',changed);
 INSERT INTO workhub.timetable_intervention_commands(school_id,membership_id,account_id,request_key,command_hash,outcome,receipt,recorded_at)
 VALUES(ctx.school_id,ctx.membership_id,ctx.account_id,p_key,h,'applied',receipt,at);
 RETURN receipt;
END $function$

CREATE OR REPLACE FUNCTION workhub_private.t3_plan(ctx workhub_private.actor_context, i jsonb, p_seed text, p_at timestamp with time zone, p_ignore_request text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE l workhub.timetable_lessons;n workhub.timetable_lessons;c workhub.timetable_school_day_changes;
 ids text[];x jsonb;rows jsonb:='[]';sources jsonb:='[]';changes jsonb:='[]';participants text[]:='{}';blocks jsonb:='[]';
 removed bigint:=0;added bigint:=0;s timestamptz;e timestamptz;day date;k text:=i->>'kind';bad text;conf text[];
BEGIN
 PERFORM workhub_private.t3_input(i);
 IF k='reopen' THEN
 IF NOT workhub_private.p5_manager(ctx) THEN RAISE EXCEPTION 'FORBIDDEN';END IF;
 SELECT * INTO c FROM workhub.timetable_school_day_changes WHERE school_id=ctx.school_id AND id=i->>'schoolDayChangeId' AND input->>'kind'='closure';
 IF c.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND';END IF;
 IF EXISTS(SELECT 1 FROM workhub.timetable_reopened_days WHERE school_id=ctx.school_id AND school_day_change_id=c.id) THEN RAISE EXCEPTION 'CONFLICT';END IF;
 IF jsonb_array_length(c.changed_lessons) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'INVALID_INPUT';END IF;
 ids:=ARRAY(SELECT a->>'id' FROM jsonb_array_elements(c.changed_lessons) a ORDER BY a->>'id');
 ELSE
 ids:=ARRAY[i->>'lessonId'];
 END IF;
 FOREACH bad IN ARRAY ids LOOP
 SELECT * INTO l FROM workhub.timetable_lessons WHERE school_id=ctx.school_id AND id=bad;
 IF l.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND';END IF;
 IF EXISTS(SELECT 1 FROM workhub.terms tt WHERE tt.school_id=ctx.school_id AND tt.id=l.term_id AND tt.state='closed') THEN RAISE EXCEPTION 'CONFLICT';END IF;
 IF k<>'reopen' AND l.version<>(i->>'expectedVersion')::integer THEN RAISE EXCEPTION 'CONFLICT';END IF;
 IF NOT(workhub_private.p5_manager(ctx) OR ctx.membership_id=ANY(l.teacher_ids)) THEN RAISE EXCEPTION 'FORBIDDEN';END IF;
 IF k='reopen' AND (l.state<>'cancelled' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(c.changed_lessons) a WHERE a->>'id'=l.id AND (a->>'version')::integer=l.version)
 OR NOT EXISTS(SELECT 1 FROM workhub.timetable_lesson_versions v WHERE v.school_id=l.school_id AND v.lesson_id=l.id AND v.version=l.version AND v.source_id=c.id AND v.change_kind='school_day')) THEN
 RAISE EXCEPTION 'CONFLICT';END IF;
 IF k IN('substitute','cancel') AND l.state<>'scheduled' OR k='makeup' AND (l.state<>'cancelled' OR l.changed_by NOT IN('school_day','intervention')) THEN RAISE EXCEPTION 'INVALID_INPUT';END IF;
 IF k IN('makeup','reopen') AND EXISTS(SELECT 1 FROM workhub.timetable_makeup_links z WHERE z.school_id=ctx.school_id AND z.original_lesson_id=l.id) THEN
 blocks:=blocks||jsonb_build_array(jsonb_build_object('code','ALREADY_MADE_UP','message','원수업에 연결된 보강이 이미 있습니다.','lessonIds',jsonb_build_array(l.id)));END IF;
 IF EXISTS(SELECT 1 FROM workhub.timetable_execution_records z WHERE z.school_id=ctx.school_id AND z.lesson_id=l.id) THEN
 blocks:=blocks||jsonb_build_array(jsonb_build_object('code','EXECUTION_EXISTS','message','실시 기록이 있는 수업은 여기서 바꾸지 않습니다.','lessonIds',jsonb_build_array(l.id)));END IF;
 IF EXISTS(SELECT 1 FROM workhub.timetable_exchange_lessons q JOIN workhub.timetable_exchange_requests r ON r.id=q.request_id
 WHERE q.school_id=ctx.school_id AND q.lesson_id=l.id AND workhub_private.t2_req_live(r,p_at))
 OR EXISTS(SELECT 1 FROM workhub.timetable_interventions r WHERE r.school_id=ctx.school_id AND r.id IS DISTINCT FROM p_ignore_request
 AND workhub_private.t3_live(r,p_at) AND EXISTS(SELECT 1 FROM jsonb_array_elements(r.plan->'sources') q WHERE q->>'id'=l.id)) THEN
 blocks:=blocks||jsonb_build_array(jsonb_build_object('code','EXISTING_REQUEST','message','이 수업에 진행 중인 변경 요청이 있습니다.','lessonIds',jsonb_build_array(l.id)));END IF;
 sources:=sources||jsonb_build_array(to_jsonb(l));n:=l;n.version:=l.version+1;n.pinned:=true;n.changed_by:='intervention';
 IF k='substitute' THEN
 IF NOT workhub_private.t3_member(ctx.school_id,i->>'substituteTeacherId') THEN RAISE EXCEPTION 'NOT_FOUND';END IF;
 IF i->>'substituteTeacherId'=ANY(l.teacher_ids) THEN RAISE EXCEPTION 'INVALID_INPUT';END IF;
 n.teacher_ids:=ARRAY[i->>'substituteTeacherId'];
 n.uses:=COALESCE((SELECT jsonb_agg(u ORDER BY u->>'id') FROM jsonb_array_elements(l.uses) u WHERE u->>'kind'<>'teacher'),'[]'::jsonb)
 ||jsonb_build_array(jsonb_build_object('id',i->>'substituteTeacherId','kind','teacher','capacity',1));
 ELSIF k='cancel' THEN n.state:='cancelled';removed:=removed+extract(epoch FROM l.ends_at-l.starts_at)::bigint;
 ELSIF k='reopen' THEN n.state:='scheduled';added:=added+extract(epoch FROM l.ends_at-l.starts_at)::bigint;
 ELSE
 n.id:='t3-'||md5(p_seed||':'||l.id);n.activity_id:='t3-'||md5(p_seed||':activity:'||l.id);n.version:=1;n.state:='scheduled';
 n.starts_at:=workhub_private.t2_parse_ts(i#>'{target,startsAt}',true);n.ends_at:=workhub_private.t2_parse_ts(i#>'{target,endsAt}',true);
 day:=workhub_private.t2_day(n.starts_at,ctx.school_timezone);n.occurrence_date:=day;
 IF n.ends_at-n.starts_at<>l.ends_at-l.starts_at OR workhub_private.t2_day(n.ends_at-interval '1 second',ctx.school_timezone)<>day
 OR day<l.occurrence_date OR NOT EXISTS(SELECT 1 FROM workhub.terms t WHERE t.school_id=l.school_id AND t.id=l.term_id AND day>=t.starts_on AND day<t.ends_on)
 OR NOT EXISTS(SELECT 1 FROM workhub.timetable_basis_revisions b CROSS JOIN jsonb_array_elements(b.basis->'slots') sl
 WHERE b.school_id=l.school_id AND b.id=l.basis_id AND sl->>'id'=ANY(l.allowed_slot_ids) AND (sl->>'day')::integer=extract(isodow FROM day)::integer
 AND workhub_private.t2_at(day,(sl->>'startMinute')::integer,ctx.school_timezone)=n.starts_at
 AND workhub_private.t2_at(day,(sl->>'endMinute')::integer,ctx.school_timezone)=n.ends_at) THEN RAISE EXCEPTION 'INVALID_INPUT';END IF;
 added:=added+extract(epoch FROM n.ends_at-n.starts_at)::bigint;
 END IF;
 IF n.starts_at<=p_at OR (k<>'makeup' AND l.starts_at<=p_at) THEN
 blocks:=blocks||jsonb_build_array(jsonb_build_object('code','PAST_LESSON','message','이미 시작한 수업은 변경하지 않습니다.','lessonIds',jsonb_build_array(l.id)));END IF;
 IF n.state<>'cancelled' AND NOT EXISTS(SELECT 1 FROM workhub.courses cc WHERE cc.school_id=ctx.school_id AND cc.id=n.course_id AND workhub_private.t2_day(n.starts_at,ctx.school_timezone)<@daterange(cc.valid_from,cc.valid_to,'[)')) THEN
 blocks:=blocks||jsonb_build_array(jsonb_build_object('code','COURSE_PERIOD','message','수업 운영 기간 밖입니다.','lessonIds',jsonb_build_array(l.id)));END IF;
 participants:=participants||l.teacher_ids||n.teacher_ids;
 IF n.state<>'cancelled' AND (workhub_private.t3_closed(ctx.school_id,workhub_private.t2_day(n.starts_at,ctx.school_timezone),n.groups,CASE WHEN k='reopen' THEN c.id END)
 OR workhub_private.t2_unavailable(n.publication_id,n.uses,n.starts_at,n.ends_at,ctx.school_timezone)) THEN
 blocks:=blocks||jsonb_build_array(jsonb_build_object('code','UNAVAILABLE','message','휴업 또는 자원 사용 불가 시간입니다.','lessonIds',jsonb_build_array(l.id)));END IF;
 -- 현재 자격과 변경일의 재직 기간을 함께 확인한다. 이름이 아니라 학교 소속 ID로 판단한다.
 IF EXISTS(SELECT 1 FROM unnest(l.teacher_ids||n.teacher_ids) m WHERE NOT workhub_private.t3_member(ctx.school_id,m)
 OR NOT EXISTS(SELECT 1 FROM workhub.memberships z WHERE z.school_id=ctx.school_id AND z.id=m
 AND workhub_private.t2_day(n.starts_at,ctx.school_timezone)<@daterange(z.valid_from,z.valid_to,'[)'))) THEN
 blocks:=blocks||jsonb_build_array(jsonb_build_object('code','PARTICIPANT_UNAVAILABLE','message','영향 교사 모두 현재 시범 자격과 변경일 재직 기간이 필요합니다.','lessonIds',jsonb_build_array(l.id)));END IF;
 rows:=rows||jsonb_build_array(to_jsonb(n));
 changes:=changes||jsonb_build_array(jsonb_build_object('before',CASE WHEN k='makeup' THEN NULL ELSE workhub_private.t2_lesson(l,false,'[]') END,'after',workhub_private.t2_lesson(n,false,'[]')));
 END LOOP;
 participants:=ARRAY(SELECT DISTINCT a FROM unnest(participants) a ORDER BY a);
 conf:=workhub_private.t2_conflicts(ctx.school_id,COALESCE((SELECT jsonb_agg(jsonb_build_object('id',a->>'id','s',a->>'starts_at','e',a->>'ends_at','uses',a->'uses'))
 FROM jsonb_array_elements(rows) a WHERE a->>'state'<>'cancelled'),'[]'),ids);
 IF cardinality(conf)>0 THEN blocks:=blocks||jsonb_build_array(jsonb_build_object('code','RESOURCE_CONFLICT','message','교사·학급·공간·수강집단의 사용 시간이 겹칩니다.','lessonIds',to_jsonb(conf)));END IF;
 IF NOT EXISTS(SELECT 1 FROM workhub_private.t3_approvers(ctx.school_id,ctx.school_today) a WHERE a.account_id<>ctx.account_id
 AND NOT EXISTS(SELECT 1 FROM workhub.memberships m WHERE m.school_id=ctx.school_id AND m.id=ANY(participants) AND m.account_id=a.account_id)) THEN
 blocks:=blocks||jsonb_build_array(jsonb_build_object('code','APPROVER_MISSING','message','요청자·영향 교사와 다른 승인 담당자가 필요합니다.','lessonIds',to_jsonb(ids)));END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('code',code,'message',message,'lessonIds',lids) ORDER BY code),'[]') INTO blocks
 FROM(SELECT b->>'code' code,min(b->>'message') message,jsonb_agg(DISTINCT lid ORDER BY lid) lids FROM jsonb_array_elements(blocks) b CROSS JOIN jsonb_array_elements(b->'lessonIds') lid GROUP BY b->>'code') grouped;
 RETURN jsonb_build_object('sources',sources,'rows',rows,'changes',changes,'participants',workhub_private.t2_teachers(participants),'blockers',blocks,
 'hours',jsonb_build_object('removedSeconds',removed,'addedSeconds',added),
 'policy',(SELECT to_jsonb(p) FROM workhub.timetable_intervention_policies p WHERE p.school_id=ctx.school_id),
 'memberships',(SELECT jsonb_agg(jsonb_build_array(m.id,m.version,m.permission_version,m.valid_from,m.valid_to,a.version,a.permission_version) ORDER BY m.id)
 FROM workhub.memberships m JOIN workhub.accounts a ON a.id=m.account_id WHERE m.school_id=ctx.school_id AND m.id=ANY(participants)));
END $function$

CREATE OR REPLACE FUNCTION workhub_private.op1_actor(p_member_id text, p_lock boolean, p_scope text)
 RETURNS workhub_private.actor_context
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE uid uuid:=auth.uid(); a workhub.accounts; m workhub.memberships; s workhub.schools; g workhub.participant_grants; ctx workhub_private.actor_context;
BEGIN
 IF public.get_my_role()='superadmin' THEN RETURN workhub_private.member_actor(p_member_id,p_lock); END IF;
 IF uid IS NULL THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
 IF p_lock THEN PERFORM 1 FROM public.users WHERE id=uid::text FOR SHARE; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.users WHERE id=uid::text AND is_active AND role='teacher') THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
 a:=workhub_private.caller_account(uid,p_lock);
 SELECT * INTO m FROM workhub.memberships WHERE id=p_member_id AND account_id=a.id;
 IF m.id IS NULL THEN RAISE EXCEPTION 'INACTIVE_MEMBERSHIP'; END IF;
 IF p_lock THEN
  SELECT * INTO s FROM workhub.schools WHERE id=m.school_id FOR SHARE;
  SELECT * INTO m FROM workhub.memberships WHERE id=p_member_id AND account_id=a.id FOR SHARE;
  SELECT * INTO g FROM workhub.participant_grants WHERE school_id=s.id AND membership_id=m.id FOR SHARE;
 ELSE
  SELECT * INTO s FROM workhub.schools WHERE id=m.school_id;
  SELECT * INTO g FROM workhub.participant_grants WHERE school_id=s.id AND membership_id=m.id;
 END IF;
 IF s.id IS NULL OR g.membership_id IS NULL OR g.auth_user_id IS DISTINCT FROM uid OR NOT g.active
 OR g.expires_at<=clock_timestamp() OR NOT(p_scope=ANY(g.scopes)) OR NOT workhub_private.op1_allowed(s.id,m.id,p_scope)
 THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
 ctx.actor_kind:='member';ctx.account_id:=a.id;ctx.membership_id:=m.id;ctx.school_id:=s.id;ctx.scope_key:='s:'||s.id;
 ctx.auth_user_id:=uid;ctx.school_today:=workhub_private.today_in(s.timezone);ctx.school_timezone:=s.timezone;
 RETURN ctx;
END $function$

CREATE OR REPLACE FUNCTION workhub_private.mp1_actor(p_member_id text, p_lock boolean)
 RETURNS workhub_private.actor_context
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_uid uuid:=auth.uid(); a workhub.accounts; s workhub.schools; m workhub.memberships;
 ctx workhub_private.actor_context;
BEGIN
 IF public.get_my_role()='superadmin' THEN RETURN workhub_private.member_actor(p_member_id,p_lock); END IF;
 IF v_uid IS NULL THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
 IF p_lock THEN PERFORM 1 FROM public.users WHERE id=v_uid::text FOR SHARE; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.users WHERE id=v_uid::text AND is_active AND role='teacher') THEN
   RAISE EXCEPTION 'FORBIDDEN'; END IF;
 a:=workhub_private.caller_account(v_uid,p_lock);
 IF a.id IS NULL OR p_member_id IS NULL THEN RAISE EXCEPTION 'INACTIVE_MEMBERSHIP'; END IF;
 SELECT * INTO m FROM workhub.memberships WHERE id=p_member_id AND account_id=a.id;
 IF FOUND THEN
   IF p_lock THEN
     SELECT * INTO s FROM workhub.schools WHERE id=m.school_id FOR SHARE;
     SELECT * INTO m FROM workhub.memberships WHERE id=p_member_id AND account_id=a.id FOR SHARE;
     PERFORM 1 FROM workhub.messaging_pilot_grants WHERE singleton FOR SHARE;
     PERFORM 1 FROM workhub.participant_grants WHERE school_id=s.id AND membership_id=m.id FOR SHARE;
   ELSE SELECT * INTO s FROM workhub.schools WHERE id=m.school_id; END IF;
 END IF;
 IF m.id IS NULL OR s.id IS NULL OR NOT workhub_private.mp1_allowed(s.id,m.id) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
 ctx.actor_kind:='member'; ctx.account_id:=a.id; ctx.membership_id:=m.id; ctx.school_id:=s.id;
 ctx.scope_key:='s:'||s.id; ctx.auth_user_id:=v_uid;
 ctx.school_today:=workhub_private.today_in(s.timezone); ctx.school_timezone:=s.timezone;
 RETURN ctx;
END $function$
